+//Rewritten from PETSc minres
+template<class T>
+void MinResQLPSymOrtho(T const a, T const b, T &c, T &s, T &r)
+{
+    if (b == 0.0) 
+    {
+        if (a == 0.0) 
+            c = 1.0;
+        else 
+            c = math::getSign(a); 
+        s = 0.0;
+        r = math::abs(a); 
+    } 
+    else if (a == 0.0) 
+    {
+        c = 0.0;
+        s = math::getSign(b);
+        r = math::abs(b);
+    } 
+    else if (math::abs(b) > math::abs(a)) 
+    {
+        T t = a / b;
+
+        s = math::getSign(b) / math::sqrt(1.0 + t * t);
+        c = s * t;
+        r = b / s;
+    } 
+    else
+    {
+        T t = b / a;
+        c = math::getSign(a) / math::sqrt(1.0 + t * t);
+        s = c * t;
+        r = a / c;
+    }
